window.addEventListener('hashchange',()=>{route();window.scrollTo({top:0,behavior:'instant'});const selected=$(`[data-tab="${tab}"]`);if(/\/(film|trana)$/.test(location.hash)&&selected)selected.focus({preventScroll:true});else $('#main').focus({preventScroll:true});});window.addEventListener('DOMContentLoaded',()=>tex());route();
